CREATE FUNCTION app.assert_draft_exit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_positions integer;
  v_filled    integer;
  v_window    interval;
BEGIN
  IF NEW.status IN ('enrollment', 'active', 'round_in_progress', 'completed')
     AND OLD.status = 'draft' THEN
    SELECT count(*) INTO v_positions
      FROM ajo_positions
     WHERE ajo_id = NEW.id AND deleted_at IS NULL;

    IF v_positions < 2 THEN
      RAISE EXCEPTION
        'ajo % cannot leave DRAFT with % position(s); at least two are required',
        NEW.id, v_positions
        USING ERRCODE = 'check_violation',
              HINT = 'An Ajo of one is a transfer, not a rotation.';
    END IF;
  END IF;

  -- ENROLLMENT -> ACTIVE either fills every position or reaches day five.
  IF NEW.status = 'active' AND OLD.status = 'enrollment' THEN
    SELECT count(*), count(*) FILTER (WHERE p.status <> 'open')
      INTO v_positions, v_filled
      FROM ajo_positions p
     WHERE p.ajo_id = NEW.id AND p.deleted_at IS NULL;

    v_window := NEW.enrollment_closes_at - NEW.enrollment_opens_at;

    IF v_filled < v_positions AND now() < NEW.enrollment_closes_at THEN
      RAISE EXCEPTION
        'ajo % cannot activate: % of % positions filled and the window closes at %',
        NEW.id, v_filled, v_positions, NEW.enrollment_closes_at
        USING ERRCODE = 'check_violation',
              HINT = 'CANONICAL.md section 3: ENROLLMENT -> ACTIVE requires '
                     'every position filled, or day five reached.';
    END IF;

    IF v_window <> interval '5 days' THEN
      RAISE EXCEPTION
        'ajo % has an enrollment window of %, which is not exactly 5 days',
        NEW.id, v_window
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- BEFORE triggers return the row to keep. Returning NULL here would make
  -- PostgreSQL drop the row silently: no error, no warning, INSERT 0 0.
  RETURN NEW;
END;
$$;


