CREATE FUNCTION app.assert_fee_matches_payment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  p_base  bigint;
  p_fee   bigint;
  p_chan  uuid;
BEGIN
  SELECT contribution_amount_kobo, fee_kobo, channel_id
    INTO p_base, p_fee, p_chan
    FROM payments
   WHERE id = NEW.payment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fee % references payment %, which does not exist',
      NEW.id, NEW.payment_id USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF NEW.contribution_amount_kobo <> p_base THEN
    RAISE EXCEPTION
      'fee % records base %, but payment % has base %',
      NEW.id, NEW.contribution_amount_kobo, NEW.payment_id, p_base
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.fee_kobo <> p_fee THEN
    RAISE EXCEPTION
      'fee % records %, but payment % charged a fee of %',
      NEW.id, NEW.fee_kobo, NEW.payment_id, p_fee
      USING ERRCODE = 'check_violation',
            HINT = 'The fee is derived, never supplied. Read it from the '
                   'payment instead of computing it a second time.';
  END IF;

  IF NEW.fee_kobo <> ((p_base * 200 + 5000) / 10000) THEN
    RAISE EXCEPTION
      'fee % of % is not 2%% half-up of base %', NEW.id, NEW.fee_kobo, p_base
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;


