CREATE FUNCTION app.assert_ledger_balanced_for_txn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count integer;
  v_sum   bigint;
BEGIN
  -- Runs from the ledger_transactions side, and catches the case a posting
  -- trigger structurally cannot: a transaction row with NO postings at all.
  SELECT count(*), COALESCE(sum(signed_kobo), 0)
    INTO v_count, v_sum
    FROM ledger_postings
   WHERE transaction_id = NEW.id;

  IF v_count < 2 OR v_sum <> 0 THEN
    RAISE EXCEPTION
      'ledger transaction % (% / %) is not a valid entry: % posting(s), sum %',
      NEW.id, NEW.kind, NEW.occurred_at, v_count, v_sum
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


