CREATE FUNCTION app.assert_ledger_sequence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_recognized_at timestamptz;
  v_target_kind   ledger_entry_type;
  v_count         integer;
  v_sum           bigint;
BEGIN
  IF NEW.kind = 'reversal' THEN
    -- CR-21, second half: reversals are one level deep. A reversal of a
    -- reversal is not a correction, it is an untraceable second correction.
    SELECT kind INTO v_target_kind
      FROM ledger_transactions
     WHERE id = NEW.reverses_transaction_id;

    IF v_target_kind = 'reversal' THEN
      RAISE EXCEPTION
        'transaction % reverses %, which is itself a reversal; '
        'reversals are one level deep (CR-21)',
        NEW.id, NEW.reverses_transaction_id
        USING ERRCODE = 'check_violation',
              HINT = 'If entry A was wrong and entry B corrected it, the fix '
                     'for B is a new entry C that explains itself, not a '
                     'reversal of B.';
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.kind <> 'payout.settled' THEN
    RETURN NULL;
  END IF;

  SELECT min(t.occurred_at)
    INTO v_recognized_at
    FROM ledger_transactions t
   WHERE t.kind       = 'payout.recognized'
     AND t.payout_id  = NEW.payout_id
     AND t.id        <> NEW.id;

  IF v_recognized_at IS NULL THEN
    RAISE EXCEPTION
      'payout.settled % references payout % with no payout.recognized entry',
      NEW.id, NEW.payout_id
      USING ERRCODE = 'check_violation',
            HINT = 'CANONICAL.md section 4 fixes the order: contribution.'
                   'received, fee.recognised, payout.recognized, payout.settled.';
  END IF;

  IF v_recognized_at > NEW.occurred_at THEN
    RAISE EXCEPTION
      'payout.settled at % precedes payout.recognized at % for payout %',
      NEW.occurred_at, v_recognized_at, NEW.payout_id
      USING ERRCODE = 'check_violation';
  END IF;

  -- "Complete" means the recognition entry is itself a valid journal entry. A
  -- half-posted recognition satisfies the ordering check and is still wrong.
  SELECT count(*), COALESCE(sum(signed_kobo), 0)
    INTO v_count, v_sum
    FROM ledger_postings
   WHERE transaction_id = (
     SELECT id FROM ledger_transactions
      WHERE kind = 'payout.recognized' AND payout_id = NEW.payout_id
      ORDER BY occurred_at LIMIT 1);

  IF v_count < 2 OR v_sum <> 0 THEN
    RAISE EXCEPTION
      'the payout.recognized entry for payout % is incomplete (% posting(s), '
      'sum %); payout.settled requires a complete recognition',
      NEW.payout_id, v_count, v_sum
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;


--

--

COMMENT ON FUNCTION app.assert_ledger_sequence() IS 'CR-17 and CR-21. Ordering is asserted on payout.settled, the only step in the canonical sequence with a prerequisite that the other three do not.';


