CREATE FUNCTION app.assert_lifecycle_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  -- CANONICAL.md section 3, the transition table, as "from>to" strings. A
  -- string rather than a two-dimensional array because unnest() over text[][]
  -- flattens in a way that has to be explained, and an adjacency list nobody
  -- can read at a glance is a table that will be edited wrongly.
  allowed text[] := ARRAY[
    'draft>enrollment',
    'enrollment>active',
    'enrollment>cancelled',
    'enrollment>frozen',
    'draft>cancelled',
    'draft>frozen',
    'active>round_in_progress',
    'active>completed',
    'active>frozen',
    'active>cancelling',
    'round_in_progress>active',
    'round_in_progress>completed',
    'round_in_progress>frozen',
    'round_in_progress>cancelling',
    'frozen>active',
    'frozen>cancelling',
    'cancelling>cancelled',
    'cancelling>active'
  ];
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;   -- not a transition
  END IF;

  -- CR-19 first: terminal is terminal, in both directions. Checked before the
  -- adjacency list so the error a caller sees for a completed Ajo is the one
  -- that explains why, rather than "no such transition".
  IF OLD.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION
      'ajo % is %, which is terminal; no further events accepted',
      OLD.id, OLD.status
      USING ERRCODE = 'check_violation',
            HINT = 'CANONICAL.md section 3: COMPLETED and CANCELLED accept no '
                   'events in either direction. Reversing one is a new Ajo.';
  END IF;

  IF NOT ((OLD.status || '>' || NEW.status) = ANY (allowed)) THEN
    RAISE EXCEPTION 'illegal Ajo transition: % -> %', OLD.status, NEW.status
      USING ERRCODE = 'check_violation',
            HINT = 'CANONICAL.md section 3 draws this state machine. The '
                   'allowed transitions from ' || OLD.status || ' are the ones '
                   'listed in app.assert_lifecycle_transition().';
  END IF;

  RETURN NEW;
END;
$$;


