CREATE FUNCTION app.assert_money_critical_has_sms() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_channel notification_channel;
BEGIN
  IF NOT (NEW.is_money_critical OR NEW.is_security) THEN
    RETURN NULL;
  END IF;

  -- One of the NEW row's own channels must be SMS.
  IF NEW.channel = 'sms' THEN
    RETURN NULL;
  END IF;

  SELECT channel INTO v_channel
    FROM notification_templates
   WHERE event_key = NEW.event_key
     AND channel = 'sms'
     AND is_active;

  IF v_channel IS NULL THEN
    RAISE EXCEPTION
      'event % is flagged % but has no active SMS template',
      NEW.event_key,
      CASE WHEN NEW.is_money_critical AND NEW.is_security THEN 'money- and security-critical'
           WHEN NEW.is_money_critical                    THEN 'money-critical'
           ELSE 'security-critical' END
      USING ERRCODE = 'check_violation',
            HINT = 'CANONICAL.md section 8: SMS is reserved for money-critical '
                   'and security-critical events. Add the sms row in the same '
                   'transaction as the first push or email row for this event.';
  END IF;

  RETURN NULL;
END;
$$;


