CREATE FUNCTION app.assert_positions_locked() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status ajo_status;
BEGIN
  IF (NEW.position_number IS DISTINCT FROM OLD.position_number)
     OR (NEW.ajo_id IS DISTINCT FROM OLD.ajo_id) THEN
    SELECT status INTO v_status FROM ajos WHERE id = NEW.ajo_id;

    IF v_status IN ('active', 'round_in_progress', 'completed', 'cancelling') THEN
      RAISE EXCEPTION
        'position % in Ajo % (%): the turn order is locked at activation',
        OLD.id, NEW.ajo_id, v_status
        USING ERRCODE = 'check_violation',
              HINT = 'Reordering after activation requires a replacement or '
                     'transfer request with member consent. See section 8.8 '
                     'CR-02 and the CANONICAL.md section 3 note on positions.';
    END IF;
  END IF;

  -- Releasing or forfeiting a position must say why, or the round pool cannot
  -- explain the gap in its contribution list.
  IF NEW.status IN ('released', 'forfeited', 'replaced')
     AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.release_reason IS NULL THEN
    RAISE EXCEPTION
      'position % moved to % without a release_reason', OLD.id, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


