CREATE FUNCTION app.assert_risk_subject_exists() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_exists boolean;
BEGIN
  v_exists := CASE NEW.subject_type
    WHEN 'user'         THEN EXISTS (SELECT 1 FROM users         WHERE id = NEW.subject_id)
    WHEN 'ajo'          THEN EXISTS (SELECT 1 FROM ajos          WHERE id = NEW.subject_id)
    WHEN 'payment'      THEN EXISTS (SELECT 1 FROM payments      WHERE id = NEW.subject_id)
    WHEN 'payout'       THEN EXISTS (SELECT 1 FROM payouts       WHERE id = NEW.subject_id)
    WHEN 'contribution' THEN EXISTS (SELECT 1 FROM contributions WHERE id = NEW.subject_id)
  END;

  IF NOT COALESCE(v_exists, false) THEN
    RAISE EXCEPTION 'risk event % targets % %, which does not exist',
      NEW.id, NEW.subject_type, NEW.subject_id
      USING ERRCODE = 'check_violation',
            HINT = 'Checked at insert only. After this row exists the subject '
                   'may be deleted and the event stays, which is the intent.';
  END IF;

  -- BEFORE triggers return the row to keep. Returning NULL here would make
  -- PostgreSQL drop the row silently: no error, no warning, INSERT 0 0.
  RETURN NEW;
END;
$$;


