CREATE FUNCTION app.assert_round_pool() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_round   uuid;
  v_stored  bigint;
  v_actual  bigint;
  v_members integer;
  v_paid    integer;
BEGIN
  -- The same function guards both sides of the invariant: a round must match
  -- its contributions, and a contribution must not change without the round
  -- being restated. The round is named `id` on rounds and `round_id` on
  -- contributions, so which one to read is a property of the table, not
  -- something to guess at.
  IF TG_TABLE_NAME = 'rounds' THEN
    v_round := NEW.id;
  ELSE
    v_round := COALESCE(NEW.round_id, OLD.round_id);
  END IF;

  SELECT base_pool_kobo INTO v_stored FROM rounds WHERE id = v_round;

  SELECT count(*),
         COALESCE(sum(c.amount_kobo) FILTER (WHERE c.status = 'paid'), 0),
         count(*) FILTER (WHERE c.status = 'paid')
    INTO v_members, v_actual, v_paid
    FROM contributions c
   WHERE c.round_id      = v_round
     AND c.superseded_at IS NULL
     AND c.deleted_at    IS NULL;

  IF v_stored IS DISTINCT FROM v_actual THEN
    RAISE EXCEPTION
      'round % records a base pool of % but its paid, unsuperseded '
      'contributions total % (% of % paid)',
      v_round, v_stored, v_actual, v_paid, v_members
      USING ERRCODE = 'check_violation',
            HINT = 'base_pool_kobo is a stored aggregate, not a field anybody '
                   'types. Restate it as coalesce(sum(amount_kobo), 0) over '
                   'paid, unsuperseded contributions in the SAME statement that '
                   'changed the contributions. The trigger is deferred to '
                   'COMMIT, so the restatement may come later in the same '
                   'transaction -- but not in the next one.';
  END IF;

  RETURN NULL;
END;
$$;


