CREATE FUNCTION app.assert_terminal_timestamps() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'completed' AND NEW.completed_at IS NULL THEN
    RAISE EXCEPTION 'ajo % is COMPLETED but has no completed_at',
      NEW.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> 'completed' AND NEW.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'ajo % has completed_at but status is %', NEW.id, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'cancelled' AND NEW.cancelled_at IS NULL THEN
    RAISE EXCEPTION 'ajo % is CANCELLED but has no cancelled_at',
      NEW.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> 'cancelled' AND NEW.cancelled_at IS NOT NULL THEN
    RAISE EXCEPTION 'ajo % has cancelled_at but status is %', NEW.id, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  -- BEFORE triggers return the row to keep. Returning NULL here would make
  -- PostgreSQL drop the row silently: no error, no warning, INSERT 0 0.
  RETURN NEW;
END;
$$;


