CREATE FUNCTION app.assert_transaction_balanced() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_txn     uuid;
  v_count   integer;
  v_sum     bigint;
BEGIN
  v_txn := COALESCE(NEW.transaction_id, OLD.transaction_id);

  SELECT count(*), COALESCE(sum(signed_kobo), 0)
    INTO v_count, v_sum
    FROM ledger_postings
   WHERE transaction_id = v_txn;

  IF v_count < 2 THEN
    RAISE EXCEPTION
      'ledger transaction % has % posting(s); a transaction needs at least two',
      v_txn, v_count
      USING ERRCODE = 'check_violation',
            HINT = 'Every entry moves money between two accounts. If you meant '
                   'to delete an entry, post a reversal instead.';
  END IF;

  IF v_sum <> 0 THEN
    RAISE EXCEPTION
      'ledger transaction % does not balance: sum(signed_kobo) = % kobo',
      v_txn, v_sum
      USING ERRCODE = 'check_violation',
            HINT = 'A balanced entry debits and credits the same total.';
  END IF;

  RETURN NULL;
END;
$$;


--

--

COMMENT ON FUNCTION app.assert_transaction_balanced() IS 'CR-16. Deferred to COMMIT so a multi-statement entry is judged as a whole.';


