CREATE FUNCTION app.audit_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'public'
    AS $$
DECLARE
  v_subject_id uuid;
  v_before     jsonb;
  v_after      jsonb;
  v_amount     bigint;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_subject_id := OLD.id;
    v_before     := to_jsonb(OLD);
    v_after      := NULL;
  ELSIF TG_OP = 'INSERT' THEN
    v_subject_id := NEW.id;
    v_before     := NULL;
    v_after      := to_jsonb(NEW);
  ELSE
    v_subject_id := NEW.id;
    v_before     := to_jsonb(OLD);
    v_after      := to_jsonb(NEW);
    -- An UPDATE that changed nothing is not an audit event. Recording it puts
    -- rows in a table that investigators read, and the cost of a noisy audit
    -- trail is that nobody reads it.
    IF v_before = v_after THEN
      RETURN NULL;
    END IF;
  END IF;

  -- Money columns touched, for the finance audit view. NULL means the row is
  -- not a money row, which is most of them. The values themselves stay in the
  -- ledger; this is a pointer, not a copy of the money.
  IF v_after IS NOT NULL AND v_after ? 'amount_kobo' THEN
    v_amount := (v_after ->> 'amount_kobo')::bigint;
  END IF;

  -- subject_type is the table name minus its plural, which is the convention
  -- every table here already follows. An audited table whose singular is not
  -- in the subject_type enum is a gap in the taxonomy, and this cast is where
  -- it surfaces -- loudly, at migration time, rather than as an unqueryable
  -- NULL six months later.
  INSERT INTO audit_logs
    (actor_user_id, actor_type, action, subject_type, subject_id,
     before_state, after_state, request_id, ip_address, amount_kobo)
  VALUES
    (NULLIF(current_setting('app.actor_user_id', true), '')::uuid,
     COALESCE(NULLIF(current_setting('app.actor_type', true), ''), 'service'),
     lower(TG_OP),
     (rtrim(TG_TABLE_NAME, 's'))::subject_type,
     v_subject_id, v_before, v_after,
     NULLIF(current_setting('app.request_id', true), ''),
     NULLIF(current_setting('app.ip_address', true), '')::inet,
     v_amount);

  RETURN NULL;
END;
$$;


--

--

COMMENT ON FUNCTION app.audit_row() IS 'SECURITY DEFINER because the auditing role must be able to write audit_logs even where it has been denied INSERT on it. The trigger fires as the table owner, which is the point: the audit trail is not writable by the role it audits, and not deletable by it either.';


--

--

CREATE FUNCTION app.current_ajo_ids() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app'
    AS $$
  SELECT m.ajo_id
    FROM ajo_members m
   WHERE m.user_id  = app.request_user_id()
     AND m.deleted_at IS NULL
     AND m.status   IN ('invited','active','defaulted');
$$;


--

--

CREATE FUNCTION app.has_platform_role(p_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app'
    AS $$
  SELECT EXISTS (
           SELECT 1
             FROM role_assignments ra
             JOIN roles r ON r.code = ra.role_id AND r.is_active
            WHERE ra.user_id    = app.request_user_id()
              AND ra.scope      = 'platform'
              AND ra.role_id    = p_role
              AND ra.revoked_at IS NULL
              AND ra.deleted_at IS NULL
              AND (ra.expires_at IS NULL OR ra.expires_at > now())
         );
$$;


--

--

CREATE FUNCTION app.is_ajo_member(p_ajo_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  -- Written as EXISTS rather than `= ANY(array(...))`: a set-returning
  -- function is not an array, and the two forms look interchangeable until the
  -- first one fails to compile.
  SELECT EXISTS (SELECT 1 FROM app.current_ajo_ids() AS live
                  WHERE live = p_ajo_id);
$$;


--

--

CREATE FUNCTION app.is_platform_staff() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT app.has_platform_role('support')
      OR app.has_platform_role('risk_officer');
$$;


--

--

CREATE FUNCTION app.reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION
    'table %.% is append-only; % is not permitted (txid=%)',
    TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP, txid_current()
    USING ERRCODE = 'restrict_violation',
          HINT = 'Corrections are made by posting a reversing entry, never by '
                 'editing or removing history.';
END;
$$;


--

--

CREATE FUNCTION app.request_actor_type() RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(
           nullif(current_setting('app.actor_type', true), ''),
           CASE WHEN app.request_user_id() IS NULL THEN 'anon' ELSE 'member' END
         );
$$;


--

--

CREATE FUNCTION app.request_user_id() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(
           nullif(current_setting('app.user_id', true), '')::uuid,
           (nullif(current_setting('request.jwt.claim.sub', true), ''))::uuid
         );
$$;


--

--

COMMENT ON FUNCTION app.request_user_id() IS 'The authenticated user for this request, or null for an anonymous one. app.user_id is authoritative; request.jwt.claim.sub is the PostgREST path.';


--

--

CREATE FUNCTION app.shares_ajo_with(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'app'
    AS $$
  SELECT EXISTS (
           SELECT 1
             FROM ajo_members mine
             JOIN ajo_members theirs ON theirs.ajo_id = mine.ajo_id
            WHERE mine.user_id    = app.request_user_id()
              AND theirs.user_id   = p_user_id
              AND mine.deleted_at  IS NULL
              AND theirs.deleted_at IS NULL
              AND mine.status   IN ('invited','active','defaulted')
              AND theirs.status  IN ('invited','active','defaulted')
         );
$$;


--

--

CREATE FUNCTION app.touch_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();
  NEW.version    := OLD.version + 1;
  RETURN NEW;
END;
$$;


--

--

CREATE FUNCTION app.uuidv7() RETURNS uuid
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
DECLARE
  b bytea;
BEGIN
  -- 48 bits of epoch milliseconds, big-endian, no sign bit issues.
  b := substring(int8send((EXTRACT(EPOCH FROM clock_timestamp()) * 1000)::bigint) FROM 3);
  -- 80 bits of randomness: the last 10 bytes of a v4 UUID.
  b := b || substring(uuid_send(gen_random_uuid()) FROM 7);
  -- RFC 9562 version 7 -> high nibble of byte 6 is 0111.
  b := set_byte(b, 6, (get_byte(b, 6) & 15) | 112);
  -- RFC 9562 variant -> top two bits of byte 8 are 10.
  b := set_byte(b, 8, (get_byte(b, 8) & 63) | 128);
  RETURN encode(b, 'hex')::uuid;
END;
$$;


--

--

COMMENT ON FUNCTION app.uuidv7() IS 'RFC 9562 UUID version 7. Used as the DEFAULT for every primary key. Time-ordered, so B-tree index inserts stay local and `ORDER BY id` is a chronological ordering for free.';


